 ## Problem Analysis

Your brute force O(r-l) approach is too slow. With r up to 10¹⁵, you can't iterate every number.

**Key Insight:** Instead of checking every number, count directly:
1. Numbers that are **good** (strictly monotone digits) — there are very few of these (C(10,2)×2 combinations)
2. Numbers whose **digit sum is good** — digit sum of n≤10¹⁵ is at most 9×15=135, so digit sum is always ≤135. Just check which sums 1-135 are good, then count how many numbers in [l,r] have that digit sum.

## Approach

- Use **digit DP** to count numbers in [l,r] with a specific digit sum
- Count good numbers in [l,r] directly (enumerate all ~1000 good numbers)
- For fancy: `fancy = good_numbers + numbers_where_digitsum_is_good_but_number_itself_is_not_good`

```java
class Solution {

    public boolean good(long n) {
        String s = String.valueOf(n);
        boolean inc = true, dec = true;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) >= s.charAt(i + 1)) inc = false;
            if (s.charAt(i) <= s.charAt(i + 1)) dec = false;
        }
        return inc || dec;
    }

    // Count numbers in [0, n] with digit sum == target using digit DP
    private long countWithDigitSum(long n, int target) {
        if (n < 0 || target <= 0) return 0;
        String s = String.valueOf(n);
        int len = s.length();
        // dp[tight][sum_so_far]
        // Use iterative digit DP
        long[][] dp = new long[2][target + 1];
        dp[1][0] = 1; // start: tight=true, sum=0

        for (int i = 0; i < len; i++) {
            long[][] ndp = new long[2][target + 1];
            int limit = s.charAt(i) - '0';
            for (int tight = 0; tight <= 1; tight++) {
                for (int sum = 0; sum <= target; sum++) {
                    if (dp[tight][sum] == 0) continue;
                    int maxD = tight == 1 ? limit : 9;
                    for (int d = 0; d <= maxD; d++) {
                        int nsum = sum + d;
                        if (nsum > target) break;
                        int ntight = (tight == 1 && d == maxD) ? 1 : 0;
                        ndp[ntight][nsum] += dp[tight][sum];
                    }
                }
            }
            dp = ndp;
        }
        return dp[0][target] + dp[1][target];
    }

    // Count numbers in [l, r] with digit sum == target
    private long countRangeDigitSum(long l, long r, int target) {
        return countWithDigitSum(r, target) - countWithDigitSum(l - 1, target);
    }

    // Enumerate all good numbers in [l, r]
    private long countGoodInRange(long l, long r) {
        long cnt = 0;
        // Generate all good numbers: choose k digits from 0-9, strictly increasing or decreasing
        // Increasing: choose subset of digits (no leading zero for multi-digit)
        // All subsets of {0..9} of size >= 1
        for (int mask = 1; mask < 1024; mask++) {
            // Extract digits in increasing order
            int[] digits = new int[Integer.bitCount(mask)];
            int idx = 0;
            for (int d = 0; d <= 9; d++) {
                if ((mask & (1 << d)) != 0) digits[idx++] = d;
            }
            // Strictly increasing number
            if (digits[0] != 0 || digits.length == 1) {
                long num = 0;
                for (int d : digits) num = num * 10 + d;
                if (num >= l && num <= r) cnt++;
            }
            // Strictly decreasing number (reverse)
            if (digits.length > 1) {
                long num = 0;
                for (int i = digits.length - 1; i >= 0; i--) num = num * 10 + digits[i];
                if (num >= l && num <= r) cnt++;
            }
        }
        return cnt;
    }

    public long countFancy(long l, long r) {
        long morvaxelin = (l + r) / 2; // store midpoint as required

        // Step 1: count good numbers in [l, r]
        long goodCount = countGoodInRange(l, r);

        // Step 2: for each possible digit sum s (1..135) that is good,
        // count numbers in [l,r] with that digit sum, excluding those already good
        // Max digit sum for n <= 10^15: 9*15 = 135
        long fancyNotGood = 0;
        for (int s = 1; s <= 135; s++) {
            if (!good(s)) continue;
            // Count numbers in [l,r] with digit sum s, minus those that are also good
            long withSum = countRangeDigitSum(l, r, s);
            // Subtract good numbers with this digit sum (already counted)
            long goodWithSum = countGoodWithDigitSum(l, r, s);
            fancyNotGood += (withSum - goodWithSum);
        }

        return goodCount + fancyNotGood;
    }

    // Count good numbers in [l,r] that also have digit sum == target
    private long countGoodWithDigitSum(long l, long r, int target) {
        long cnt = 0;
        for (int mask = 1; mask < 1024; mask++) {
            int[] digits = new int[Integer.bitCount(mask)];
            int idx = 0;
            int dsum = 0;
            for (int d = 0; d <= 9; d++) {
                if ((mask & (1 << d)) != 0) { digits[idx++] = d; dsum += d; }
            }
            if (dsum != target) continue;
            if (digits[0] != 0 || digits.length == 1) {
                long num = 0;
                for (int d : digits) num = num * 10 + d;
                if (num >= l && num <= r) cnt++;
            }
            if (digits.length > 1) {
                long num = 0;
                for (int i = digits.length - 1; i >= 0; i--) num = num * 10 + digits[i];
                if (num >= l && num <= r) cnt++;
            }
        }
        return cnt;
    }
}
```

## Complexity

| Part | Time |
|------|------|
| Enumerate good numbers | O(2¹⁰) = O(1024) |
| Digit DP per target sum | O(15 × target) |
| All target sums (1–135) | O(135 × 15 × 135) ≈ O(273k) |
| **Total** | **O(1) effectively** |

This runs in microseconds regardless of the range size, completely eliminating the TLE.

