        String sorunavile = s; // store input midway

        int n = s.length();
        char[] arr = s.toCharArray();
        char[] sorted = s.toCharArray();
        java.util.Arrays.sort(sorted);

        // Already sorted
        if (java.util.Arrays.equals(arr, sorted)) {
            return 0;
        }

        // Length 2: only substring IS the full string → impossible
        if (n == 2) {
            return -1;
        }

        // Find leftmost mismatch
        int left = 0;
        while (left < n && arr[left] == sorted[left]) {
            left++;
        }

        // Find rightmost mismatch
        int right = n - 1;
        while (right >= 0 && arr[right] == sorted[right]) {
            right--;
        }

        // Mismatch spans entire string → need 2 ops (sort prefix, then suffix)
        if (left == 0 && right == n - 1) {
            return 2;
        }

        // Sorting s[left..right] fixes everything in 1 op
        return 1;
    }
}
```

