  // Typing animation
  const lines = [
    '> building something cool...',
    '> git commit -m "another day, another feature"',
    '> solving dp problems at 2am...',
    '> const dev = new Developer("Arnav");',
  ];
  let lineIdx = 0, charIdx = 0, deleting = false;
  const el = document.getElementById('typing');

  function type() {
    const current = lines[lineIdx];
    if (!deleting) {
      el.textContent = current.slice(0, ++charIdx);
      if (charIdx === current.length) {
        deleting = true;
        setTimeout(type, 2200);
        return;
      }
    } else {
      el.textContent = current.slice(0, --charIdx);
      if (charIdx === 0) {
        deleting = false;
        lineIdx = (lineIdx + 1) % lines.length;
        setTimeout(type, 400);
        return;
      }
    }
    setTimeout(type, deleting ? 28 : 55);
  }
  setTimeout(type, 800);

  // Animated counters
  function animateCounter(el, target) {
    let start = 0;
    const step = target / 40;
    const tick = () => {
      start = Math.min(start + step, target);
      el.querySelector('.stat-num').childNodes[0].textContent = Math.floor(start);
      if (start < target) requestAnimationFrame(tick);
    };
    tick();
  }

  const observer = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        const boxes = e.target.querySelectorAll('.stat-box');
        const targets = [300, 5, 3];
        boxes.forEach((b, i) => animateCounter(b, targets[i]));
        observer.unobserve(e.target);
      }
    });
  }, { threshold: 0.5 });

  const statsGrid = document.querySelector('.stats-grid');
  if (statsGrid) observer.observe(statsGrid);
</script>
