npm init -y
npm install express mongoose dotenv bcryptjs jsonwebtoken cors helmet morgan express-validator
npm install --save-dev nodemon
```

Then update your `package.json` scripts section to look like this:

```json
"scripts": {
  "start": "node index.js",
  "dev": "nodemon index.js"
}
```

---

### **Step 2 — `.env` file** (in your `server/` root)

Create a file called `.env` — **never commit this to GitHub!**

```env
PORT=5000
MONGO_URI=mongodb://localhost:27017/lifeline
JWT_SECRET=your_super_secret_key_change_this
JWT_EXPIRE=7d
NODE_ENV=development
```

Also create a `.gitignore` in `server/`:
```
node_modules/
.env
```

---

### **Step 3 — `config/db.js`**

This connects your app to MongoDB:

```js
const mongoose = require("mongoose");

const connectDB = async () => {
  try {
    const conn = await mongoose.connect(process.env.MONGO_URI);
    console.log(`✅ MongoDB Connected: ${conn.connection.host}`);
  } catch (error) {
    console.error(`❌ Error: ${error.message}`);
    process.exit(1); // Kill server if DB fails
  }
};

module.exports = connectDB;
```

---

### **Step 4 — `config/config.js`**

Central place for all your constants (blood groups, roles, etc.):

```js
module.exports = {
  BLOOD_GROUPS: ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"],

  USER_ROLES: {
    DONOR: "donor",
    HOSPITAL: "hospital",
    BLOOD_BANK: "bloodBank",
    ADMIN: "admin",
  },

  REQUEST_STATUS: {
    PENDING: "pending",
    APPROVED: "approved",
    FULFILLED: "fulfilled",
    REJECTED: "rejected",
    EXPIRED: "expired",
  },

  URGENCY_LEVELS: {
    ROUTINE: "routine",
    URGENT: "urgent",
    EMERGENCY: "emergency",
  },

  INVENTORY_STATUS: {
    SURPLUS: "surplus",     // Green on heatmap
    MODERATE: "moderate",   // Yellow on heatmap
    SHORTAGE: "shortage",   // Red on heatmap
  },

  // Donors can donate whole blood every 56 days (8 weeks)
  DONATION_COOLDOWN_DAYS: 56,

  // Min hemoglobin to be eligible (g/dL)
  MIN_HEMOGLOBIN: 12.5,
};
```

---

### **Step 5 — `index.js`** (your main server entry point, in `server/` root)

```js
const express = require("express");
const dotenv = require("dotenv");
const cors = require("cors");
const helmet = require("helmet");
const morgan = require("morgan");
const connectDB = require("./config/db");

// Load env vars
dotenv.config();

// Connect to database
connectDB();

const app = express();

// ── Middleware ──────────────────────────────────────────
app.use(express.json());         // Parse JSON bodies
app.use(express.urlencoded({ extended: true }));
app.use(cors());                 // Allow frontend to talk to backend
app.use(helmet());               // Security headers
app.use(morgan("dev"));          // Request logging in terminal

// ── Health Check Route ──────────────────────────────────
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "🩸 Life Line API is running!",
    version: "1.0.0",
  });
});

// ── Routes (we'll add these in Phase 4) ────────────────
// app.use("/api/auth",      require("./routes/authRoutes"));
// app.use("/api/donors",    require("./routes/donorRoutes"));
// app.use("/api/hospitals", require("./routes/hospitalRoutes"));
// app.use("/api/bloodbank", require("./routes/bloodBankRoutes"));
// app.use("/api/requests",  require("./routes/requestRoutes"));
// app.use("/api/inventory", require("./routes/inventoryRoutes"));
// app.use("/api/alerts",    require("./routes/alertRoutes"));
// app.use("/api/analytics", require("./routes/analyticsRoutes"));

// ── Global Error Handler ────────────────────────────────
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.statusCode || 500).json({
    success: false,
    message: err.message || "Internal Server Error",
  });
});

// ── 404 Handler ─────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ success: false, message: "Route not found" });
});

// ── Start Server ─────────────────────────────────────────
const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});
```

---

### **Step 6 — `utils/errorResponse.js`**

A small helper class for clean error handling:

```js
class ErrorResponse extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

module.exports = ErrorResponse;
```

### **Step 7 — `utils/asyncHandler.js`**

Wraps async route handlers so you don't need `try/catch` in every controller:

```js
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

module.exports = asyncHandler;
```

