### `models/Donor.js`
```js
const mongoose = require("mongoose");
const bcrypt = require("bcryptjs");
const { BLOOD_GROUPS, DONATION_COOLDOWN_DAYS } = require("../config/config");

const donorSchema = new mongoose.Schema(
  {
    name: { type: String, required: true, trim: true },
    email: { type: String, required: true, unique: true, lowercase: true },
    password: { type: String, required: true, minlength: 6 },
    phone: { type: String, required: true },
    bloodGroup: { type: String, required: true, enum: BLOOD_GROUPS },
    dateOfBirth: { type: Date, required: true },
    gender: { type: String, enum: ["male", "female", "other"] },

    address: {
      street: String,
      city: { type: String, required: true },
      state: String,
      pincode: String,
    },

    location: {
      type: { type: String, default: "Point" },
      coordinates: [Number], // [longitude, latitude]
    },

    // Health & Eligibility
    hemoglobin: { type: Number, default: null },
    isEligible: { type: Boolean, default: true },
    lastDonationDate: { type: Date, default: null },
    nextEligibleDate: { type: Date, default: null },

    // Gamification
    totalDonations: { type: Number, default: 0 },
    livsSaved: { type: Number, default: 0 },
    badges: [{ type: String }],
    donorCircle: { type: mongoose.Schema.Types.ObjectId, ref: "CommunityEngagement" },

    // Account
    isActive: { type: Boolean, default: true },
    isVerified: { type: Boolean, default: false },
  },
  { timestamps: true }
);

// Hash password before saving
donorSchema.pre("save", async function (next) {
  if (!this.isModified("password")) return next();
  this.password = await bcrypt.hash(this.password, 10);
  next();
});

// Auto-calculate next eligible donation date
donorSchema.pre("save", function (next) {
  if (this.lastDonationDate) {
    const next_date = new Date(this.lastDonationDate);
    next_date.setDate(next_date.getDate() + DONATION_COOLDOWN_DAYS);
    this.nextEligibleDate = next_date;
    this.isEligible = new Date() >= next_date;
  }
  next();
});

// Method to compare passwords on login
donorSchema.methods.matchPassword = async function (enteredPassword) {
  return await bcrypt.compare(enteredPassword, this.password);
};

donorSchema.index({ location: "2dsphere" }); // For geo queries (Emergency Circle Alert)

module.exports = mongoose.model("Donor", donorSchema);
```

