const bcrypt = require("bcrypt"); // ← was missing

// ── Extracted sub-schema for cleaner validation ───────
const reviewSchema = new mongoose.Schema(
  {
    userId:  { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },
    rating:  { type: Number, min: 1, max: 5, required: true },
    comment: { type: String, maxlength: 500, trim: true },
  },
  { _id: false }
);

const hospitalSchema = new mongoose.Schema(
  {
    hospitalID: {
      type:      String,
      minlength: 6,
      maxlength: 14,
      match:     [/^[A-Z0-9\-]+$/, "Invalid hospital ID format"], // ← added pattern
      required:  true,
      unique:    true,
      uppercase: true,
      trim:      true,
    },
    name: {
      type:      String,
      minlength: 3,
      maxlength: 50,
      required:  true,
      trim:      true,
    },
    hospitalHeadID: {
      type:     mongoose.Schema.Types.ObjectId,
      ref:      "Employee",
      required: true,
    },
    type: {
      type:     String,
      enum:     ["General", "Multi-specialty", "Super-specialty", "Clinic"],
      required: true,
    },
    ownership: {
      type:     String,
      maxlength: 50,
      required: true,
      trim:     true,
    },
    licence: {
      type:      String,
      maxlength: 50,
      required:  true,
      trim:      true,
    },
    accreditation:  { type: String, maxlength: 50, trim: true },
