    emgServices:    { type: String, maxlength: 150, trim: true },

    // ── Auth ─────────────────────────────────────────
    email: {
      type:      String,
      required:  true,
      minlength: 5,
      unique:    true,
      lowercase: true,
      trim:      true,
      match:     [/^\S+@\S+\.\S+$/, "Invalid email format"], // ← added regex
    },
    password: {
      type:      String,
      minlength: 6,
      required:  true,
    },

    // ── Address ──────────────────────────────────────
