content.text:
 Looking at your Hospital schema, here are a few improvements and fixes I'd suggest:

**Issues & Improvements:**

1. **Missing `bcrypt` import** — `bcrypt` is used in the pre-save hook but never imported
2. **Missing `timestamps`** — useful for `createdAt`/`updatedAt` tracking
3. **`location` field** — the nested `type` key conflicts with Mongoose's reserved `type` keyword; needs proper GeoJSON structure
4. **`reviews`** — better extracted to a separate schema for cleanliness and validation
5. **`hospitalID` format** — no pattern validation (e.g. regex) despite having length constraints
6. **`email`** — no regex format validation

```javascript
const mongoose = require("mongoose");
const bcrypt = require("bcrypt"); // ← was missing

// ── Extracted sub-schema for cleaner validation ───────
const reviewSchema = new mongoose.Schema(
  {
    userId:  { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },
    rating:  { type: Number, min: 1, max: 5, required: true },
    comment: { type: String, maxlength: 500, trim: true },
  },
  { _id: false }
);

const hospitalSchema = new mongoose.Schema(
  {
    hospitalID: {
      type:      String,
      minlength: 6,
      maxlength: 14,
      match:     [/^[A-Z0-9\-]+$/, "Invalid hospital ID format"], // ← added pattern
      required:  true,
      unique:    true,
      uppercase: true,
      trim:      true,
    },
    name: {
      type:      String,
      minlength: 3,
      maxlength: 50,
      required:  true,
      trim:      true,
    },
    hospitalHeadID: {
      type:     mongoose.Schema.Types.ObjectId,
      ref:      "Employee",
      required: true,
    },
    type: {
      type:     String,
      enum:     ["General", "Multi-specialty", "Super-specialty", "Clinic"],
      required: true,
    },
    ownership: {
      type:     String,
      maxlength: 50,
      required: true,
      trim:     true,
    },
    licence: {
      type:      String,
      maxlength: 50,
      required:  true,
      trim:      true,
    },
    accreditation:  { type: String, maxlength: 50, trim: true },
    accCertificates: { type: [String], default: [] },
    emgServices:    { type: String, maxlength: 150, trim: true },

    // ── Auth ─────────────────────────────────────────
    email: {
      type:      String,
      required:  true,
      minlength: 5,
      unique:    true,
      lowercase: true,
      trim:      true,
      match:     [/^\S+@\S+\.\S+$/, "Invalid email format"], // ← added regex
    },
    password: {
      type:      String,
      minlength: 6,
      required:  true,
    },

    // ── Address ──────────────────────────────────────
    address: {
      type:      String,
      maxlength: 150,
      required:  true,
      trim:      true,
    },
    landmark:     { type: String, maxlength: 50,  trim: true },
    cityOrVillage: {
      type:      String,
      maxlength: 50,
      required:  true,
      trim:      true,
    },
    pincode: {
      type:      String,
      minlength: 6,
      maxlength: 6,
      match:     [/^\d{6}$/, "Pincode must be 6 digits"], // ← added digit-only check
      required:  true,
    },
    district: { type: String, maxlength: 50, required: true, trim: true },
    state:    { type: String, maxlength: 50, required: true, trim: true },

    // ── GeoJSON — fixed conflicting nested "type" key ─
    location: {
      type: {
        type:    String,
        enum:    ["Point"],
        default: "Point",
      },
      coordinates: {
        type:    [Number], // [longitude, latitude]
        default: undefined,
      },
    },

    image: { type: String, required: true },

    status: {
      type:    Number,
      enum:    [0, 1, 2],
      default: 0,
    }, // 0=Inactive, 1=Active, 2=Suspended

    // ── Contact ──────────────────────────────────────
    phoneNo1: { type: String, maxlength: 15, required: true, trim: true },
    phoneNo2: { type: String, maxlength: 15, trim: true },

    totalEmp: { type: Number, min: 0, max: 1000000 }, // ← added min: 0

    reviews: { type: [reviewSchema], default: [] },
  },
  {
    timestamps: true, // ← adds createdAt & updatedAt automatically
  }
);

// ── Hash password only when modified ─────────────────
hospitalSchema.pre("save", async function (next) {
  if (!this.isModified("password")) return next();
  this.password = await bcrypt.hash(this.password, 10);
  next();
});

// ── Geo index for location-based search ──────────────
hospitalSchema.index({ location: "2dsphere" });

